"""Group incidents by the set of services they touch."""
from collections import defaultdict

SAMPLE = [
    {"id": "INC-1", "services": ["api", "db"]},
    {"id": "INC-2", "services": ["db", "api"]},
    {"id": "INC-3", "services": ["api"]},
    {"id": "INC-4", "services": ["api", "api", "db"]},
]


def group_by_services(incidents):
    """Return {frozenset(services): [incident, ...]}.

    frozenset is the right key type here for two reasons: it is hashable, and it
    is order- and duplicate-insensitive, which is exactly the equality the
    grouping is supposed to express. A sorted tuple would also be hashable but
    would keep duplicates distinct unless deduplicated first.
    """
    groups = defaultdict(list)
    for incident in incidents:
        key = frozenset(incident["services"])
        groups[key].append(incident)
    return dict(groups)


def services_of(key):
    """Return the service names in a grouping key, as a sorted list."""
    return sorted(key)


if __name__ == "__main__":
    for key, members in group_by_services(SAMPLE).items():
        print(services_of(key), [i["id"] for i in members])

