from grouping import SAMPLE, group_by_services, services_of


def test_does_not_raise():
    group_by_services(SAMPLE)


def test_order_insensitive_keys_merge():
    groups = group_by_services(SAMPLE)
    by_services = {tuple(services_of(k)): [i["id"] for i in v] for k, v in groups.items()}
    assert by_services[("api", "db")] == ["INC-1", "INC-2", "INC-4"]
    assert by_services[("api",)] == ["INC-3"]


def test_group_count():
    assert len(group_by_services(SAMPLE)) == 2

from grouping import SAMPLE, group_by_services


def test_keys_are_hashable():
    for key in group_by_services(SAMPLE):
        hash(key)


def test_keys_are_not_strings():
    for key in group_by_services(SAMPLE):
        assert not isinstance(key, str), "the key was serialised to a string"


def test_keys_contain_service_names():
    keys = list(group_by_services(SAMPLE))
    assert any("api" in key and "db" in key for key in keys)
